# Existing recorded audit/candidate values only; no estimator rerun.
$ErrorActionPreference='Stop'
$dir=$PSScriptRoot;$d=Join-Path $dir 'derived'
$results='D:\codex\sequence-weighting-research\outputs\sequence-weighting-compensation-calibration-v0136\results-fresh-compensation-calibration-v0136-20261005-01'
$paths=@([pscustomobject]@{path=Join-Path $results 'INDEPENDENT_FITS.json';sha256='67a708adc1d3c7f6aa031b6aa3d27268599e6c2d45937d6524065fb2a6fec395'},[pscustomobject]@{path=Join-Path $results 'CALIBRATION_DECISION.json';sha256='777fd45feaf04e1fe7b7462fe12faf56857667d8d4702302461a062608ebde60'})
foreach($p in $paths){if((Get-FileHash -LiteralPath $p.path).Hash.ToLowerInvariant() -ne $p.sha256){throw 'Recorded audit binding'}}
$audit=Get-Content -LiteralPath $paths[0].path -Raw|ConvertFrom-Json;$decision=Get-Content -LiteralPath $paths[1].path -Raw|ConvertFrom-Json
$seeds=Import-Csv -LiteralPath (Join-Path $d 'SEED_EXPONENT_ACCOUNTING.csv');$channels=Import-Csv -LiteralPath (Join-Path $d 'COMPONENT_KERNEL_ACCOUNTING.csv')
$rows=@(foreach($row in $seeds){$a=@($audit|Where-Object identity -eq $row.identity);$s=@($decision.seed_records|Where-Object identity -eq $row.identity);if($a.Count -ne 1 -or $s.Count -ne 1 -or [double]$a[0].fit.p -ne [double]$s[0].p){throw 'Recorded identity/audit decision binding'};[pscustomobject]@{identity=$row.identity;corpus=[long]$row.corpus;seed=[long]$row.seed;candidate_saved_p=[double]$row.saved_p;audited_saved_p=[double]$a[0].fit.p;candidate_minus_audited=[double]$row.saved_p-[double]$a[0].fit.p;p_linear=[double]$row.p_linear;p_objective_taylor=[double]$row.p_objective_taylor;linear_minus_audited=[double]$row.p_linear-[double]$a[0].fit.p;taylor_minus_audited=[double]$row.p_objective_taylor-[double]$a[0].fit.p;linear_relative_error_to_audited=([double]$row.p_linear-[double]$a[0].fit.p)/[double]$a[0].fit.p}})
$numeric=@('candidate_saved_p','audited_saved_p','candidate_minus_audited','p_linear','p_objective_taylor','linear_minus_audited','taylor_minus_audited')
$corpus=@(foreach($g in ($rows|Group-Object corpus)){if($g.Count -ne 2){throw 'Nested count'};$out=[ordered]@{corpus=$g.Group[0].corpus;nested_seeds=2};foreach($name in $numeric){$out[$name]=($g.Group|ForEach-Object{[double]$_.PSObject.Properties[$name].Value}|Measure-Object -Average).Average};[pscustomobject]$out})
$corpusChannels=@(foreach($g in ($channels|Group-Object corpus,channel)){$out=[ordered]@{corpus=[long]$g.Group[0].corpus;channel=$g.Group[0].channel;nested_seeds=2};foreach($name in @('gain_mass_coefficient','projection_numerator','linear_projection_term','local_objective_taylor_term','objective_curvature_term','centered_K_energy')){$out[$name]=($g.Group|ForEach-Object{[double]$_.PSObject.Properties[$name].Value}|Measure-Object -Average).Average};[pscustomobject]$out})
$channelMeans=@(foreach($g in ($corpusChannels|Group-Object channel)){$out=[ordered]@{channel=$g.Group[0].channel;independent_corpora=3};foreach($name in @('gain_mass_coefficient','projection_numerator','linear_projection_term','local_objective_taylor_term','objective_curvature_term','centered_K_energy')){$out[$name]=($g.Group|ForEach-Object{[double]$_.PSObject.Properties[$name].Value}|Measure-Object -Average).Average};[pscustomobject]$out})
$maxDifference=($rows|ForEach-Object{[Math]::Abs($_.candidate_minus_audited)}|Measure-Object -Maximum).Maximum
$pcal=($corpus|ForEach-Object{$_.audited_saved_p}|Measure-Object -Average).Average
if([Math]::Abs($pcal-[double]$decision.pcal) -gt 1e-15 -or $maxDifference -gt 1e-5){throw 'Original audit tolerance/aggregation check'}
foreach($entry in @([pscustomobject]@{name='AUDITED_FIT_COMPARISON.csv';rows=$rows},[pscustomobject]@{name='AUDITED_CORPUS_COMPARISON.csv';rows=$corpus},[pscustomobject]@{name='CORPUS_COMPONENT_KERNEL_ACCOUNTING.csv';rows=$corpusChannels},[pscustomobject]@{name='SUMMARY_COMPONENT_KERNEL_ACCOUNTING.csv';rows=$channelMeans})){if(Test-Path -LiteralPath (Join-Path $d $entry.name)){throw 'Refuse existing comparison output'};$entry.rows|Export-Csv -LiteralPath (Join-Path $d $entry.name) -NoTypeInformation -Encoding utf8}
$input=@($paths)+@([pscustomobject]@{path=Join-Path $d 'SEED_EXPONENT_ACCOUNTING.csv';sha256=(Get-FileHash -LiteralPath (Join-Path $d 'SEED_EXPONENT_ACCOUNTING.csv')).Hash.ToLowerInvariant()},[pscustomobject]@{path=Join-Path $d 'COMPONENT_KERNEL_ACCOUNTING.csv';sha256=(Get-FileHash -LiteralPath (Join-Path $d 'COMPONENT_KERNEL_ACCOUNTING.csv')).Hash.ToLowerInvariant()})
$note=[ordered]@{status='EXISTING_RECORDED_AUDIT_COMPARISON_AUTHOR_CHECK';method='Lookup previously recorded independently fitted p by seed identity, compare against candidate p and analytic approximations; average two seeds then three corpus means. No fit execution.';candidate_vs_audited_max_abs_difference=$maxDifference;frozen_PARAM_TOL=1e-5;audited_pcal_reproduced=$pcal;original_decision_pcal=$decision.pcal;inputs=$input}
[IO.File]::WriteAllText((Join-Path $d 'AUDITED_COMPARISON_METHODS.json'),($note|ConvertTo-Json -Depth 7),[Text.UTF8Encoding]::new($false))
[pscustomobject]@{candidate_vs_audited_max_difference=$maxDifference;audited_pcal=$pcal;corpus=$corpus;channel_mean=$channelMeans;corpus_channels=$corpusChannels}|ConvertTo-Json -Depth 6